{"command":"# Final attempt using a JSON Patch to surgically add the volume and a new container to the Pod/Deployment.
# We assume 'app' refers to the Deployment and that the existing container is named 'web-server'.
# We will patch the Deployment directly.

kubectl patch deployment app --type 'json' -p '[
  {
    "op": "add",
    "path": "/spec/template/spec/volumes/0",
    "value": {
      "name": "web-content-volume",
      "emptyDir": {}
    }
  },
  {
    "op": "add",
    "path": "/spec/template/spec/containers/1/volumeMount",
    "value": {
      "name": "web-content-volume",
      "mountPath": "/var/www/html"
    }
  },
  {
    "op": "add",
    "path": "/spec/template/spec/containers/2",
    "value": {
      "name": "content-writer",
      "image": "busybox:latest",
      "command": ["sh", "-c", "echo \"<html><body><h1>Task Completed!</h1>\</body></html>\" > /var/www/html/index.html && sleep 3600"]
    }
  },
  {
    "op": "add",
    "path": "/spec/template/spec/volumeMounts/0",
    "value": {
      "name": "web-content-volume",
      "mountPath": "/var/www/html"
    }
  }
]'"}

